import { createSlice, configureStore } from '@reduxjs/toolkit'

const counterSlice = createSlice({
  name: 'counter',
  initialState: { value: 0 },
  reducers: {
    increment: (state) => { state.value += 1 },
    addBy: (state, action) => { state.value += action.payload },
  },
})

const store = configureStore({ reducer: { counter: counterSlice.reducer } })
store.dispatch(counterSlice.actions.increment())
store.dispatch(counterSlice.actions.addBy(4))
console.log(store.getState().counter.value)

import { createSlice } from '@reduxjs/toolkit'

const todosSlice = createSlice({
  name: 'todos',
  initialState: [{ id: 1, done: false }],
  reducers: {
    toggleTodo: (state, action) => {
      const todo = state.find(item => item.id === action.payload)
      if (todo) todo.done = !todo.done
    },
    replaceTodos: (state, action) => action.payload,
  },
})

export const { toggleTodo, replaceTodos } = todosSlice.actions
export default todosSlice.reducer

import { configureStore, createSlice } from '@reduxjs/toolkit'
import { Provider, useSelector } from 'react-redux'

const slice = createSlice({
  name: 'counter',
  initialState: { value: 0 },
  reducers: { increment: state => { state.value += 1 } },
})
const store = configureStore({ reducer: slice.reducer })

function Counter() {
  const value = useSelector(state => state.value)
  return <output>{value}</output>
}

export function App() {
  return <Provider store={store}><Counter /></Provider>
}

